package submission

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"strings"
	"time"
)

// Storage keeps source files under DATA_DIR. Paths are relative and always
// generated by the server (BACKEND_CONTEXT.md §7).
type Storage interface {
	// Save writes content durably (file and directory fsync) and returns its
	// relative path.
	Save(content []byte, now time.Time) (string, error)
	Read(relPath string) ([]byte, error)
	Remove(relPath string) error
}

const sourceRoot = "submissions"

type fsStorage struct {
	dataDir string
}

func NewStorage(dataDir string) Storage {
	return &fsStorage{dataDir: dataDir}
}

func (s *fsStorage) Save(content []byte, now time.Time) (string, error) {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", fmt.Errorf("generate file name: %w", err)
	}
	rel := path.Join(sourceRoot, now.UTC().Format("2006"), now.UTC().Format("01"), hex.EncodeToString(b[:])+".cpp")
	full := filepath.Join(s.dataDir, filepath.FromSlash(rel))
	dir := filepath.Dir(full)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return "", fmt.Errorf("create source directory: %w", err)
	}
	f, err := os.OpenFile(full, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
	if err != nil {
		return "", fmt.Errorf("create source file: %w", err)
	}
	if _, err := f.Write(content); err != nil {
		f.Close()
		os.Remove(full)
		return "", fmt.Errorf("write source file: %w", err)
	}
	if err := f.Sync(); err != nil {
		f.Close()
		os.Remove(full)
		return "", fmt.Errorf("sync source file: %w", err)
	}
	if err := f.Close(); err != nil {
		os.Remove(full)
		return "", fmt.Errorf("close source file: %w", err)
	}
	if d, err := os.Open(dir); err == nil {
		// Persist the directory entry too, so an acknowledged file survives
		// a crash.
		err = d.Sync()
		d.Close()
		if err != nil {
			return "", fmt.Errorf("sync source directory: %w", err)
		}
	}
	return rel, nil
}

func (s *fsStorage) resolve(relPath string) (string, error) {
	clean := path.Clean(relPath)
	if clean != relPath || !strings.HasPrefix(clean, sourceRoot+"/") || strings.Contains(clean, "..") {
		return "", errors.New("invalid source path")
	}
	return filepath.Join(s.dataDir, filepath.FromSlash(clean)), nil
}

func (s *fsStorage) Read(relPath string) ([]byte, error) {
	full, err := s.resolve(relPath)
	if err != nil {
		return nil, err
	}
	return os.ReadFile(full)
}

func (s *fsStorage) Remove(relPath string) error {
	full, err := s.resolve(relPath)
	if err != nil {
		return err
	}
	return os.Remove(full)
}
